    for k,tt in enumerate(at):
        i = np.argmin(abs(t-tt))
        rows.append((p["probe_id"],tt,r[i],v[i],a[k]))

def body_inv(r,pw,bs):
    s=np.zeros(2)
    for b in bs:
        d=b-r; R=np.linalg.norm(d)
        s+= d/(R**pw)
    return s

def build(names):
    A=[];Y=[]
    for pid,tt,r,v,a in rows:
        f=[]
        for nm in names:
            if nm.startswith("B"): f.append(body_inv(r,int(nm[1]),bodies))
            elif nm=="V": f.append(-v)
            elif nm=="R": f.append(-r)
            elif nm=="C": f.append(np.array([1.0,0.0]))  # constant x? skip
        A.append(np.concatenate([np.asarray(x) for x in f])); Y.append(a)
    return np.array(A),np.array(Y)

for names in [["B3"],["B2"],["B1"],["B2","V"],["B3","V"],["B2","B3"],["B2","V","R"],["B2","B1"],["B1","B3"],["B2","V","B1"],["B3","B2","V"]]:
    A,Y=build(names)
