def feat(name,r,v):
    if name.startswith("B"):
        pw=float(name[1:]); s=np.zeros(2)
        for b in bodies:
            d=b-r; R=np.linalg.norm(d); s+= d/(R**pw)
        return s
    if name=="V": return -v
    if name=="V2": return -v*np.linalg.norm(v)
    if name=="V3": return -v*np.linalg.norm(v)**2
    if name=="R": return -r
    if name=="rotV": return np.array([-v[1],v[0]])
    if name=="ex": return np.array([1.0,0.0])
    if name=="ey": return np.array([0.0,1.0])
    if name=="yhat": return np.array([0.0,1.0])*r[1]
    raise ValueError(name)

names=["B0","B1","B2","B3","B4","V","V2","V3","R","rotV","ex","ey"]
def fit(sub):
    A=[];Y=[]
    for pid,tt,r,v,a in rows:
        fs=[feat(n,r,v) for n in sub]
        A.append([f[0] for f in fs]); Y.append(a[0])
        A.append([f[1] for f in fs]); Y.append(a[1])
    A=np.array(A);Y=np.array(Y)
    c,_,_,_=np.linalg.lstsq(A,Y,rcond=None)
    p=A@c; return np.sqrt(np.mean((p-Y)**2)),c
