for pid in ids:
    if pid not in ps: continue
    p=ps[pid]; t=np.array(p["times"]); r=np.array(p["r_obs"]); v=np.array(p["v_obs"])
    at=np.array(p["a_est_times"]); a=np.array(p["a_est"])
    for i,tt in enumerate(at):
        j=int(np.argmin(np.abs(t-tt))); rr=r[j]; vv=v[j]
        extra=a[i]+k*(rr-c); sp2=vv@vv
        if sp2<1e-6: continue
        recs.append([rr[0],rr[1],(extra@np.array([vv[1],-vv[0]]))/sp2])
A=np.array(recs); X,Y,AL=A.T
B=np.array([[-2.,0.],[2.,0.],[0.,3.]])
D=np.linalg.norm(np.stack([X[:,None]-B[None,:,0],Y[:,None]-B[None,:,1]],axis=2),axis=2)  # (n,3)
def res_fun(th,model):
    if model=="inv":
        mu=th[:3]; s=th[3]; pred=(mu[None,:]/(D+s)).sum(1)
    elif model=="inv2":
        mu=th[:3]; s=th[3]; pred=(mu[None,:]/(D**2+s**2)).sum(1)
    elif model=="sqrt":
        mu=th[:3]; s=th[3]; pred=(mu[None,:]/np.sqrt(D**2+s**2)).sum(1)
    elif model=="exp":
        mu=th[:3]; L=th[3]; pred=(mu[None,:]*np.exp(-D/L)).sum(1)
    return pred-AL
