                for b in bodies:
                    d=b-r; R=np.linalg.norm(d); row+=list(d/R**3)
            if term=="inv2":
                for b in bodies:
                    d=b-r; R=np.linalg.norm(d); row+=list(d/R**2)
            if term=="inv1":
                for b in bodies:
                    d=b-r; R=np.linalg.norm(d); row+=list(d/R)
            if term=="lin":
                for b in bodies:
