import numpy as np
from scipy.integrate import solve_ivp
from scipy.optimize import least_squares
p1=inputs["probes"][0]; p2=inputs["probes"][1]

def sim(p, k, kap, cx, cy):
    r0=p["initial_conditions"]["r0"]; v0=p["initial_conditions"]["v0"]; t0=p["initial_conditions"]["t0"]
    t=np.array(p["times"])
    def f(t,s):
        x,y,vx,vy=s
        return [vx,vy, -k*(x-cx)+kap*vy, -k*(y-cy)-kap*vx]
    sol=solve_ivp(f,[t0,t[-1]],[r0[0],r0[1],v0[0],v0[1]],t_eval=t,rtol=1e-10,atol=1e-12)
    return sol.y.T  # (N,4)

for (k,kap,cx,cy) in [(0.3,0.663,0.0,1.0)]:
    for p in (p1,p2):
        s=sim(p,k,kap,cx,cy); ro=np.array(p["r_obs"])
        err=np.linalg.norm(s[:,:2]-ro,axis=1)
        print(f"{p['probe_id']} k={k} kap={kap}: maxposerr={err.max():.4f} finalerr={err[-1]:.4f}")
        print("  pred r at t:", np.round(s[:,:2],3).tolist())
        print("  obs  r at t:", np.round(ro,3).tolist())

