    for b in B:
        dx=X[:,0]-b[0]; dy=X[:,1]-b[1]; r2=dx*dx+dy*dy
        ax+= -(2*c2*dx+4*c4*dx*r2)
        ay+= -(2*c2*dy+4*c4*dy*r2)
    return np.column_stack([ax,ay])
