    R.append(r[idx]); A.append(a)
R=np.vstack(R);A=np.vstack(A)
B=np.array([[-2.0,0.0],[2.0,0.0],[0.0,3.0]])
def field(R,p,kind):
    acc=np.zeros_like(R)
    if kind=="plummer":
        k12,k3,s=p
        ks=[k12,k12,k3]
        for b,k in zip(B,ks):
            d=b-R; r2=(d**2).sum(1)
            acc+= k*d/(r2+s**2)[:,None]**1.5
    elif kind=="soft1r":
        k12,k3,s=p
        ks=[k12,k12,k3]
        for b,k in zip(B,ks):
            d=b-R; r2=(d**2).sum(1)
            acc+= k*d/(r2+s**2)[:,None]
    elif kind=="gauss":
        k12,k3,s=p
        ks=[k12,k12,k3]
        for b,k in zip(B,ks):
            d=b-R; r2=(d**2).sum(1)
            acc+= k*d*np.exp(-r2/(2*s**2))[:,None]
    elif kind=="pow":
        k12,k3,s,pw=p
        ks=[k12,k12,k3]
        for b,k in zip(B,ks):
            d=b-R; r2=(d**2).sum(1)
            acc+= k*d/(r2+s**2)[:,None]**(pw/2)
    elif kind=="linear":
        k12,k3=p
        ks=[k12,k12,k3]
        for b,k in zip(B,ks):
            acc+= k*(b-R)
    elif kind=="gauss_far":
        # gaussian in distance without factor d? use d normalized
        k12,k3,s=p
        ks=[k12,k12,k3]
        for b,k in zip(B,ks):
            d=b-R; r2=(d**2).sum(1)
            acc+= k*d/np.sqrt(r2)[:,None]*np.exp(-r2/(2*s**2))[:,None]
    return acc
def fit(kind,x0):
    f=lambda p:(field(R,p,kind)-A).ravel()
    o=least_squares(f,x0,max_nfev=20000)
    rmse=np.sqrt((o.fun**2).mean())
    return kind,np.round(o.x,5).tolist(),rmse
