def build(extra):
    def rhs_factory(th):
        k,cx,cy,w=th[:4];c=np.array([cx,cy]);g=th[4] if len(th)>4 else 0.0
        def rhs(t,s):
            r=s[:2];v=s[2:];u=r-c
            base=-k*u+w*np.array([v[1],-v[0]])
            a=base+g*extra(u,v)
            return np.concatenate([v,a])
        return rhs
    return rhs_factory

