    rhs=rhf(th);out=[]
    for r0,v0,t0,tt,ro in dlist:
        sol=solve_ivp(rhs,[t0,tt[-1]],[*r0,*v0],t_eval=tt,rtol=1e-11,atol=1e-13,method='DOP853')
