bodies = np.array([[-2.,0.],[2.,0.],[0.,3.]])

def make_traj(p):
    return np.array(p["times"]), np.array(p["r_obs"])

def rollout(law, r0, v0, t_eval):
    def f(t,s):
        r=s[:2]; v=s[2:]
        a=law(t,r,v)
        return np.concatenate([v,a])
    s0=np.concatenate([r0,v0])
    sol=solve_ivp(f,[t_eval[0],t_eval[-1]],s0,t_eval=t_eval,rtol=1e-9,atol=1e-11)
    return sol.y[:2].T

# candidates
def law_power_gen(n, ks):
    def law(t,r,v):
        a=np.zeros(2)
        for b,k in zip(bodies,ks):
            d=b-r; a+=k*d/np.linalg.norm(d)**n
        return a
    return law

def fit(n, shared=False):
    if shared:
        def resid(p):
            ks=[p[0]]*3
            law=law_power_gen(n,ks)
            res=[]
            for pr in probes:
                t,r=make_traj(pr)
                rp=rollout(law,r[0],np.array(pr["v_obs"][0]),t)
                res.append((rp-r).ravel())
            return np.concatenate(res)
        p0=[0.3]
