        def resid(p):
            law=law_power_gen(n,p)
            res=[]
            for pr in probes:
                t,r=make_traj(pr)
                rp=rollout(law,r[0],np.array(pr["v_obs"][0]),t)
                res.append((rp-r).ravel())
            return np.concatenate(res)
        p0=[0.3,0.3,0.3]
    sol=least_squares(resid,p0,method='lm',max_nfev=200)
    return sol.x, np.sqrt(np.mean(sol.fun**2))

