from scipy.optimize import least_squares
probes=inputs["probes"]
def make(p): return np.array(p["times"]),np.array(p["r_obs"])
def rollout(polyx,polyy,r0,v0,te):
    def a_of(r):
        x,y=r
        return np.array([polyx(x,y),polyy(x,y)])
    def f(t,s): return np.concatenate([s[2:],a_of(s[:2])])
    sol=solve_ivp(f,[te[0],te[-1]],np.concatenate([r0,v0]),t_eval=te,rtol=1e-11,atol=1e-13)
    return sol.y[:2].T

def fitpoly(deg,label):
    nterm=(deg+1)*(deg+2)//2
    def resid(c):
        cx=c[:nterm]; cy=c[nterm:]
        def px(x,y):
            s=0;i=0
            for d in range(deg+1):
                for k in range(d+1):
                    s+=cx[i]*x**(d-k)*y**k; i+=1
            return s
        def py(x,y):
            s=0;i=0
            for d in range(deg+1):
                for k in range(d+1):
                    s+=cy[i]*x**(d-k)*y**k; i+=1
            return s
        res=[]
        for pr in probes:
            t,r=make(pr)
            rp=rollout(px,py,r[0],np.array(pr["v_obs"][0]),t)
            res.append((rp-r).ravel())
        return np.concatenate(res)
    c0=np.zeros(2*nterm); c0[0]=0.0; c0[nterm]=0.29; 
    if nterm>1: c0[1]=-0.31; c0[nterm+2]=-0.30
    sol=least_squares(resid,c0,method='lm',max_nfev=500)
    print(label,"pos rmse",f"{np.sqrt(np.mean(sol.fun**2)):.3e}","maxres",f"{np.max(np.abs(sol.fun)):.2e}")
    return sol.x
